const fs=require('fs');
const out=[];
for(const f of fs.readdirSync('.')){
  const t=fs.readFileSync(f,'utf8');
  const m=t.match(/\*\*Combat Level\*\*\s*\|\s*([^|\n]+?)\s*\|/);
  if(!m) continue;
  const lvls=[...m[1].matchAll(/(\d+)/g)].map(x=>+x[1]);
  if(!lvls.length) continue;
  const lo=Math.min(...lvls);
  const coords=[...t.matchAll(/\((\d{4}),\s*(\d{4})\)/g)].map(x=>[+x[1],+x[2]]);
  const hp=t.match(/\*\*Hitpoints\*\*\s*\|\s*([^|\n]+?)\s*\|/);
  const agg=t.match(/\*\*Aggressive\*\*\s*\|\s*([^|\n]+?)\s*\|/);
  out.push({name:t.split('\n')[0].replace('# ',''),lo,hi:Math.max(...lvls),hp:hp?hp[1]:'?',agg:agg?agg[1]:'',coords:coords.slice(0,8)});
}
const near=out.filter(o=>o.lo<=8 && o.coords.some(c=>c[0]>=3150&&c[0]<=3400&&c[1]>=3100&&c[1]<=3400));
near.sort((a,b)=>a.lo-b.lo);
for(const o of near) console.log(o.lo+'-'+o.hi, o.name.padEnd(26), 'hp:'+o.hp, 'agg:'+o.agg, JSON.stringify(o.coords.filter(c=>c[0]>=3150&&c[0]<=3400&&c[1]>=3100&&c[1]<=3400)).slice(0,6));
"

