async function ensureFood(){
  const s=sdk.getState();
  if(s.player.hitpoints<=6){
    const b=sdk.findInventoryItem(/bread/i) ?? sdk.findInventoryItem(/shrimps/i);
    if(b) await bot.eatFood(b);
  }
}
async function kill(pattern, ms=90_000){
  const t0=Date.now();
  let last=sdk.getState().player.hitpoints;
  while(Date.now()-t0<ms){
    await bot.dismissBlockingUI();
    const t=sdk.findNearbyNpc(pattern,{reachable:true});
    if(!t){
      const any=sdk.getState().nearbyNpcs.find(n=>pattern.test(n.name)&&n.combatLevel>0);
      if(!any) return {ok:true, secs:((Date.now()-t0)/1000).toFixed(1)};
      await bot.walkTo(any.worldX, any.worldZ, 2);
      continue;
    }
    const r=await bot.attack(t);
    if(!r.success && r.reason && r.reason!=='already_attacking') { await new Promise(x=>setTimeout(x,1000)); }
    while(sdk.getState().player.combat?.inCombat){ await sdk.waitForTicks(2); }
    const now=sdk.getState();
    if(now.player.hitpoints<last) last=now.player.hitpoints;
    await ensureFood();
    if(now.player.hitpoints<=2) return {ok:false, reason:'low hp', secs:((Date.now()-t0)/1000).toFixed(1)};
  }
  return {ok:false, reason:'timeout', secs:((Date.now()-t0)/1000).toFixed(1)};
}
